import Foundation

/**
 * The demo dashboard's dates (#416, ADR 0021 section 5). The bundled payload
 * (`demo-dashboard.<language>.json` in NetricsUI, generated by
 * `packages/contracts/src/tv-demo-payload.test.ts`, `pnpm demo:tv`) is from
 * one fixed instant, `generatedAt`. Before it is shown it is moved to now:
 *
 * - ages (`updatedAt`, `lastSuccessAt`, `createdAt`) stay as old relative to
 *   now as they were relative to `generatedAt` ("updated 3 min. ago");
 * - every other instant (chart buckets, a goal's period end) keeps its wall
 *   clock time and moves by the whole days between the generation day and
 *   today, read in the device's time zone, so daily buckets still start at
 *   midnight and the last one is today;
 * - every `timeZone` (the payload's, a clock's) becomes the device's.
 */
public enum DemoPayload {
    /** The instant the bundled payload pretends to be from (`DEMO_GENERATED_AT`). */
    public static let generatedAt = ISODate.parse("2026-10-29T09:00:00.000Z")!

    static let ageKeys: Set<String> = ["updatedAt", "lastSuccessAt", "createdAt"]

    public struct NotAnObject: Error {}

    /** The payload's JSON moved to `now` in `timeZone`. */
    public static func retime(_ data: Data, now: Date, timeZone: TimeZone) throws -> Data {
        guard let root = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            throw NotAnObject()
        }
        let source = (root["timeZone"] as? String).flatMap(TimeZone.init(identifier:)) ?? .gmt
        let shift = WallClockShift(from: source, to: timeZone, generatedAt: generatedAt, now: now)

        func walk(_ value: Any, key: String?) -> Any {
            switch value {
            case let object as [String: Any]:
                return object.reduce(into: [String: Any]()) { result, entry in
                    result[entry.key] = walk(entry.value, key: entry.key)
                }
            case let array as [Any]:
                return array.map { walk($0, key: key) }
            case let text as String:
                if key == "timeZone" { return timeZone.identifier }
                guard text.count >= 20, text.contains("T"), let date = ISODate.parse(text) else { return text }
                if let key, ageKeys.contains(key) {
                    return ISODate.format(now.addingTimeInterval(date.timeIntervalSince(generatedAt)))
                }
                return ISODate.format(shift.apply(date))
            default:
                return value
            }
        }
        return try JSONSerialization.data(withJSONObject: walk(root, key: nil))
    }
}

/** The same wall-clock time, whole days later, from one time zone into another. */
struct WallClockShift {
    let from: Calendar
    let to: Calendar
    let days: Int
    private static let civil: Calendar = {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = .gmt
        return calendar
    }()

    init(from source: TimeZone, to target: TimeZone, generatedAt: Date, now: Date) {
        var from = Calendar(identifier: .gregorian)
        from.timeZone = source
        var to = Calendar(identifier: .gregorian)
        to.timeZone = target
        self.from = from
        self.to = to
        let start = Self.day(from.dateComponents([.year, .month, .day], from: generatedAt))
        let end = Self.day(to.dateComponents([.year, .month, .day], from: now))
        days = Self.civil.dateComponents([.day], from: start, to: end).day ?? 0
    }

    private static func day(_ components: DateComponents) -> Date {
        civil.date(from: DateComponents(year: components.year, month: components.month, day: components.day))
            ?? Date(timeIntervalSince1970: 0)
    }

    func apply(_ date: Date) -> Date {
        var wall = from.dateComponents([.year, .month, .day, .hour, .minute, .second], from: date)
        guard let moved = Self.civil.date(byAdding: .day, value: days, to: Self.day(wall)) else { return date }
        let day = Self.civil.dateComponents([.year, .month, .day], from: moved)
        wall.year = day.year
        wall.month = day.month
        wall.day = day.day
        return to.date(from: wall) ?? date.addingTimeInterval(Double(days) * 86_400)
    }
}
